// A static, navigable mind map generated from the chapter content.
function mindmap(){
 const branch=(i,side)=>`<div class="mm-branch ${side}" data-chapter="${i+1}" style="--branch:${['#dd784e','#ddad50','#639d80','#49959c','#6e83b3','#9e7bb2','#d27e87','#c49a58','#5d9e91','#718bb5','#b684a2'][i]}"><button class="mm-branch-button" type="button" aria-expanded="false" aria-controls="mm-topics-${i+1}"><span class="mm-number">${String(i+1).padStart(2,'0')}</span><span class="mm-label">${esc(titles[i])}<small>${LESSONS[i].sections.length} 个知识点</small></span><span class="mm-toggle" aria-hidden="true">+</span></button><div class="mm-topic-wrap" id="mm-topics-${i+1}" hidden><div class="mm-topic-list">${LESSONS[i].sections.map((s,j)=>`<a href="#chapter/${i+1}/topic/${j}" class="mm-topic">${esc(s[0])}</a>`).join('')}</div></div></div>`;
 return `<div class="atlas-head"><div><span class="atlas-eyebrow">GIS STUDY ATLAS / MIND MAP</span><h1 class="page-title">知识思维导图</h1><p class="page-lead">沿着章节展开，从整体结构走进每一个知识点。</p></div><a class="atlas-switch" href="#graph">切换至知识图谱</a></div><div class="mm-toolbar"><div class="mm-tools-main"><label for="mapFilter">聚焦章节</label><select id="mapFilter"><option value="all">全部章节</option>${titles.map((x,i)=>`<option value="${i+1}">第 ${i+1} 章 · ${esc(x)}</option>`).join('')}</select><button id="expandMap" type="button">展开全部</button><button id="collapseMap" type="button">收起全部</button></div><div class="mm-zoom"><button id="mm-minus" type="button" aria-label="缩小思维导图">−</button><output id="mm-zoom-value">100%</output><button id="mm-plus" type="button" aria-label="放大思维导图">＋</button><button id="mm-center" type="button">居中</button></div></div><div class="mm-info">点击章节展开知识点，点击知识点进入正文。可拖动空白处或使用滚动条浏览，触屏可滑动。</div><div class="mm-viewport" id="mm-viewport" tabindex="0" aria-label="可拖动和滚动的思维导图画布"><div class="mm-stage" id="mm-stage"><div class="mm-tree"><div class="mm-column mm-left">${[0,1,2,3,4,5].map(i=>branch(i,'left')).join('')}</div><div class="mm-center"><div class="mm-root"><span>GIS STUDY ATLAS</span><strong>地理信息系统<br>原理</strong><small>从概念到应用</small></div></div><div class="mm-column mm-right">${[6,7,8,9,10].map(i=>branch(i,'right')).join('')}</div></div></div></div><div class="mm-footer"><span>11 个章节 · ${LESSONS.reduce((a,c)=>a+c.sections.length,0)} 个知识主题</span><span>内容按教材与课件整理</span></div>`
}
function initMindmap(){
 const viewport=document.getElementById('mm-viewport'),stage=document.getElementById('mm-stage'),filter=document.getElementById('mapFilter'),branches=[...document.querySelectorAll('.mm-branch')],zoomValue=document.getElementById('mm-zoom-value');let zoom=1;
 const open=(branch,on)=>{const btn=branch.querySelector('.mm-branch-button');btn.setAttribute('aria-expanded',String(on));branch.querySelector('.mm-topic-wrap').hidden=!on;btn.querySelector('.mm-toggle').textContent=on?'−':'+'};
 branches.forEach(branch=>branch.querySelector('.mm-branch-button').addEventListener('click',()=>{const opening=branch.querySelector('.mm-branch-button').getAttribute('aria-expanded')!=='true';open(branch,opening);if(opening)requestAnimationFrame(()=>{const r=branch.querySelector('.mm-topic-wrap').getBoundingClientRect(),v=viewport.getBoundingClientRect();if(r.left<v.left+20)viewport.scrollLeft+=r.left-v.left-20;else if(r.right>v.right-20)viewport.scrollLeft+=r.right-v.right+20})}));
 filter.onchange=()=>{branches.forEach(b=>{b.hidden=filter.value!=='all'&&b.dataset.chapter!==filter.value;open(b,filter.value!=='all'&&!b.hidden)});center()};
 document.getElementById('expandMap').onclick=()=>branches.filter(b=>!b.hidden).forEach(b=>open(b,true));document.getElementById('collapseMap').onclick=()=>branches.forEach(b=>open(b,false));
 function center(){requestAnimationFrame(()=>{viewport.scrollLeft=(viewport.scrollWidth-viewport.clientWidth)/2;viewport.scrollTop=Math.max(0,(viewport.scrollHeight-viewport.clientHeight)/2)})}
 function setZoom(v){zoom=Math.max(.6,Math.min(1.4,Math.round(v*10)/10));stage.style.zoom=zoom;zoomValue.textContent=Math.round(zoom*100)+'%';center()}
 document.getElementById('mm-minus').onclick=()=>setZoom(zoom-.1);document.getElementById('mm-plus').onclick=()=>setZoom(zoom+.1);document.getElementById('mm-center').onclick=center;
 let drag=null;viewport.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('a,button,select'))return;drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')});viewport.addEventListener('pointermove',e=>{if(drag){viewport.scrollLeft=drag.left-(e.clientX-drag.x);viewport.scrollTop=drag.top-(e.clientY-drag.y)}});for(const event of ['pointerup','pointercancel','lostpointercapture'])viewport.addEventListener(event,()=>{drag=null;viewport.classList.remove('dragging')});center()
}
